479	    /**
480	     * 결제 및 배송 요청 정보의 유효성을 검사합니다.
481	     *
482	     * @param requestDto 결제 및 배송 요청 정보
483	     * @throws InvalidPaymentShipmentDataException 결제 및 배송 정보가 유효하지 않은 경우
484	     */
485	    private void validatePaymentShipmentRequest(PayAndShipmentRequestDto requestDto) {
486	        if (requestDto.getPaymentRequest() == null) {
487	            throw new InvalidPaymentShipmentDataException("결제 정보가 없습니다.");
488	        }
489	
490	        if (requestDto.getReceiverName() == null || requestDto.getReceiverName().trim().isEmpty()) {
491	            throw new InvalidPaymentShipmentDataException("수령인 이름이 없습니다.");
492	        }
493	
494	        if (requestDto.getReceiverPhone() == null || requestDto.getReceiverPhone().trim().isEmpty()) {
495	            throw new InvalidPaymentShipmentDataException("수령인 전화번호가 없습니다.");
496	        }
497	
498	        if (requestDto.getPostalCode() == null || requestDto.getPostalCode().trim().isEmpty()) {
499	            throw new InvalidPaymentShipmentDataException("우편번호가 없습니다.");
500	        }
501	
502	        if (requestDto.getAddress() == null || requestDto.getAddress().trim().isEmpty()) {
503	            throw new InvalidPaymentShipmentDataException("주소가 없습니다.");
504	        }
505	    }
